#' Confounding functions
#'
#' Various confounding functions for use with
#' \code{\link{causalsens}}.
#' @aliases one.sided alignment one.sided.att alignment.att
#' @param alpha vector of confounding values to use in the
#' sensitivity analysis.
#' @param pscores vector of propensity scores for each unit.
#' @param treat vector of treatment values for each unit.
#' @export
one.sided <- function(alpha, pscores, treat) {
  adj <- alpha * (1 - pscores) * treat - alpha * pscores * (1 - treat)
  return(adj)
}
#' @rdname one.sided
#' @export
alignment <- function(alpha, pscores, treat) {
  adj <- alpha * (1 - pscores) * treat + alpha * pscores * (1 - treat)
  return(adj)
}
#' @rdname one.sided
#' @export
one.sided.att <- function(alpha, pscores, treat) {
  adj <- -alpha  * (1 - treat)
  return(adj)
}
#' @rdname one.sided
#' @export
alignment.att <- function(alpha, pscores, treat) {
  adj <- alpha  * (1 - treat)
  return(adj)
}

adjust_coef_with_binary <-
  function(effect_observed,
           exposed_confounder_prev,
           unexposed_confounder_prev,
           confounder_outcome_effect,
           loglinear = FALSE,
           verbose = getOption("tipr.verbose", TRUE)) {
    check_prevalences(unexposed_confounder_prev, exposed_confounder_prev)
    if (loglinear) {
      confounding_factor <- log((exp(confounder_outcome_effect) * exposed_confounder_prev + (1 - exposed_confounder_prev)) /
                                  (
                                    exp(confounder_outcome_effect) * unexposed_confounder_prev + (1 - unexposed_confounder_prev)
                                  ))
      effect_adj <- effect_observed - confounding_factor
      o <- tibble::tibble(
        effect_adjusted = effect_adj,
        effect_observed = effect_observed,
        exposed_confounder_prev = exposed_confounder_prev,
        unexposed_confounder_prev = unexposed_confounder_prev,
        confounder_outcome_effect = confounder_outcome_effect
      )
    } else {
      o <- adjust_coef(
        effect_observed = effect_observed,
        exposure_confounder_effect = exposed_confounder_prev - unexposed_confounder_prev,
        confounder_outcome_effect = confounder_outcome_effect,
        verbose = FALSE
      )
    }

